import React, { useState, useRef, useCallback } from 'react';
import { View, Text, TouchableOpacity, Dimensions, TextInput, TextInputProps } from 'react-native';

import { useContexState } from '../../../hooks/context';
import { styles } from './styles';

import api from '../../../services/api';

import { Entypo } from '@expo/vector-icons';

export function RegisterMenu() {
    const [value, onChangeText] = useState('Buscar');

    const ref = useRef<TextInput>(null);
    const [LoadAddCart, setLoadAddCart] = useState(false);

    const {
        shoppingCartItem,
        selectedNumber,
        paymentMenuActive,
        registerMenuActive
    } = useContexState();

    const {
        setShoppingCartItem,
        setPaymentMenuActive,
        setRegisterMenuActive
    } = useContexState();

    const conta = (shoppingCartItem.length) * 19.90;
    const price = (conta).toLocaleString("pt-BR", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    });


    function Input({ style }: TextInputProps) {
        return (
            <TextInput
                style={[styles.input, style]}
                onChangeText={text => {/*filterString(text)*/ }}
                //  value={value}
                maxLength={20}
                autoCorrect={false}
                placeholderTextColor='#fff'
                onFocus={() => { }}
                ref={ref}
            />

        )
    }


    function InputTelePhone({ style }: TextInputProps) {
        return (
            <TextInput
                style={[styles.input, style]}
                onChangeText={text => {/*filterString(text)*/ }}
                //  value={value}
                maxLength={9}
                keyboardType={'numeric'}
                autoCorrect={false}
                placeholderTextColor='#fff'
                onFocus={() => { }}
                ref={ref}
            />

        )
    }



    function InputDDD({ style }: TextInputProps) {



        return (
            <TextInput
                style={[styles.input, style]}
                onChangeText={text => { }}
                //  value={value}
                maxLength={3}
                keyboardType={'numeric'}
                autoCorrect={false}
                placeholderTextColor='#fff'
                onFocus={() => { }}
                ref={ref}
            />

        )
    }




    function Menu() {


        return (
            <>
                <Text style={{ color: '#fff', fontSize: 16, textAlign: 'center', marginVertical: 6 }}>{<Text style={{ fontSize: 40 }}>{shoppingCartItem.length}</Text>}{"\n"}NÚMEROS POR APENAS{"\n"}{<Text style={{ fontSize: 25 }}>R$ {price}</Text>}</Text>
                <View style={{ width: 250 }} >
                    <Text style={{ color: '#fff', fontSize: 20 }}>Nome Completo*</Text>
                    <Input />
                </View>

                <View style={{ flexDirection: 'row', flex: 1, marginTop: 10 }}>
                    <View style={{ width: 70 }}>
                        <Text style={{ color: '#fff', fontSize: 20 }}>DDD*</Text>
                        <InputDDD style={{ marginRight: 10 }} />
                    </View>

                    <View style={{ width: 180 }}>
                        <Text style={{ color: '#fff', fontSize: 20 }}>Telefone*</Text>
                        <InputTelePhone />
                    </View>


                </View>

                <TouchableOpacity style={styles.buttonPay} >
                    <Text style={{ color: '#fff', fontSize: 30, textAlign: 'center' }}>Concluir</Text>
                    <Text style={{ color: '#fff', fontSize: 16, textAlign: 'center' }}>Link de Pagamento com PIX</Text>
                </TouchableOpacity>
            </>
        );
    }


    return (
        registerMenuActive ?
            <>
                <TouchableOpacity onPress={() => {
                    setRegisterMenuActive(false);
                }} style={{
                    position: 'absolute',
                    alignItems: 'center',
                    justifyContent: 'center',
                    minWidth: Dimensions.get('window').width,
                    minHeight: Dimensions.get('window').height
                }} />

                <View style={styles.container} >
                    <Menu />
                </View>
            </> : null
    );
};
